<?php
/**
 * Main web entry point and server-rendered application interface.
 *
 * Routes requests by the `page` query parameter, handles POST actions for
 * authentication and appointment workflows, and renders HTML views for
 * patients, doctors, and administrators.
 */
require __DIR__.'/../backend/config.php';
require __DIR__.'/../backend/includes/functions.php';
refresh_user($pdo);
$page=$_GET['page'] ?? 'home';
$allowed=['home','login','signup','logout','dashboard','doctors','doctor','bookings','schedule','admin_doctors','cancel','complete','toggle_doctor'];
if (!in_array($page,$allowed,true)) $page='home';

if ($page==='logout') { session_destroy(); session_start(); flash('You have been logged out.'); redirect('index.php'); }
if ($_SERVER['REQUEST_METHOD']==='POST') {
    csrf_check(); $action=$_POST['action'] ?? '';
    if ($action==='login') {
        $email=strtolower(trim($_POST['email'] ?? '')); $password=$_POST['password'] ?? '';
        $q=$pdo->prepare('SELECT user_id,full_name,email,password_hash,role,is_active FROM users WHERE email=? LIMIT 1'); $q->execute([$email]); $u=$q->fetch();
        if ($u && (int)$u['is_active']===1 && password_verify($password,$u['password_hash'])) { session_regenerate_id(true); unset($u['password_hash']); $_SESSION['user']=$u; redirect('index.php?page=dashboard'); }
        flash('Invalid email/password or inactive account.','error'); redirect('index.php?page=login');
    }
    if ($action==='signup') {
        $name=trim($_POST['full_name'] ?? ''); $email=strtolower(trim($_POST['email'] ?? '')); $password=$_POST['password'] ?? '';
        if ($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || strlen($password)<8) { flash('Enter a name, valid email, and password with at least 8 characters.','error'); redirect('index.php?page=signup'); }
        try { $q=$pdo->prepare("INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,'patient')"); $q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]); flash('Account created. Please log in.'); redirect('index.php?page=login'); }
        catch (PDOException $e) { flash('That email may already be registered.','error'); redirect('index.php?page=signup'); }
    }
    if ($action==='book') {
        require_role('patient'); $slotId=(int)($_POST['slot_id'] ?? 0); $patient=(int)current_user()['user_id'];
        try { $pdo->beginTransaction(); $q=$pdo->prepare('SELECT s.slot_id,s.doctor_id,s.start_at,s.status,u.is_active FROM appointment_slots s JOIN doctors d ON d.doctor_id=s.doctor_id JOIN users u ON u.user_id=d.user_id WHERE s.slot_id=? FOR UPDATE'); $q->execute([$slotId]); $slot=$q->fetch();
            if (!$slot || $slot['status']!=='available' || !(int)$slot['is_active'] || strtotime($slot['start_at'])<=time()) throw new RuntimeException('This slot is no longer available.');
            $q=$pdo->prepare("INSERT INTO appointments(patient_id,slot_id,status) VALUES(?,?,'confirmed')"); $q->execute([$patient,$slotId]);
            $q=$pdo->prepare("UPDATE appointment_slots SET status='booked' WHERE slot_id=? AND status='available'"); $q->execute([$slotId]); if ($q->rowCount()!==1) throw new RuntimeException('This slot was just booked by someone else.');
            $pdo->commit(); flash('Appointment booked successfully.');
        } catch (Throwable $e) { if ($pdo->inTransaction()) $pdo->rollBack(); flash($e instanceof RuntimeException ? $e->getMessage() : 'Could not book this slot. It may already be taken.','error'); }
        redirect('index.php?page=doctors');
    }
    if ($action==='cancel') {
        require_role('patient','doctor','admin'); $appointmentId=(int)($_POST['appointment_id'] ?? 0); $u=current_user();
        try { $pdo->beginTransaction(); $sql='SELECT a.appointment_id,a.patient_id,a.slot_id,a.status,s.start_at,d.user_id AS doctor_user_id FROM appointments a JOIN appointment_slots s ON s.slot_id=a.slot_id JOIN doctors d ON d.doctor_id=s.doctor_id WHERE a.appointment_id=? FOR UPDATE'; $q=$pdo->prepare($sql); $q->execute([$appointmentId]); $a=$q->fetch();
            if (!$a || $a['status']!=='confirmed' || strtotime($a['start_at'])<=time()) throw new RuntimeException('This appointment can no longer be cancelled.');
            if ($u['role']==='patient' && (int)$a['patient_id']!==(int)$u['user_id']) throw new RuntimeException('You cannot cancel another patient\'s appointment.');
            if ($u['role']==='doctor' && (int)$a['doctor_user_id']!==(int)$u['user_id']) throw new RuntimeException('You cannot cancel another doctor\'s appointment.');
            $pdo->prepare("UPDATE appointments SET status='cancelled',cancelled_at=NOW() WHERE appointment_id=?")->execute([$appointmentId]); $pdo->prepare("UPDATE appointment_slots SET status='available' WHERE slot_id=?")->execute([$a['slot_id']]); $pdo->commit(); flash('Appointment cancelled.');
        } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack(); flash($e instanceof RuntimeException?$e->getMessage():'Cancellation failed.','error'); }
        redirect('index.php?page=bookings');
    }
    if ($action==='complete') {
        require_role('doctor','admin'); $id=(int)($_POST['appointment_id'] ?? 0); $q=$pdo->prepare('SELECT a.appointment_id,s.start_at,d.user_id FROM appointments a JOIN appointment_slots s ON s.slot_id=a.slot_id JOIN doctors d ON d.doctor_id=s.doctor_id WHERE a.appointment_id=?'); $q->execute([$id]); $a=$q->fetch();
        if ($a && (current_user()['role']==='admin' || (int)$a['user_id']===(int)current_user()['user_id']) && $a['start_at']<=date('Y-m-d H:i:s')) { $pdo->prepare("UPDATE appointments SET status='completed' WHERE appointment_id=? AND status='confirmed'")->execute([$id]); $pdo->prepare("UPDATE appointment_slots s JOIN appointments a ON a.slot_id=s.slot_id SET s.status='available' WHERE a.appointment_id=?")->execute([$id]); flash('Appointment marked completed.'); } else flash('Could not complete this appointment.','error');
        redirect('index.php?page=bookings');
    }
    if ($action==='save_schedule') {
        require_role('doctor'); $doctorId=doctor_id_for_user($pdo,(int)current_user()['user_id']); if(!$doctorId){flash('Doctor profile not found.','error');redirect('index.php?page=dashboard');}
        try { $pdo->beginTransaction(); $q=$pdo->prepare('DELETE FROM doctor_schedules WHERE doctor_id=?'); $q->execute([$doctorId]);
            for($day=1;$day<=7;$day++){ if(empty($_POST['enabled'][$day])) continue; $start=$_POST['start'][$day]??''; $end=$_POST['end'][$day]??''; if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$start)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$end)||$start>=$end) throw new RuntimeException('Choose valid start/end times for each enabled day.'); $q=$pdo->prepare('INSERT INTO doctor_schedules(doctor_id,day_of_week,start_time,end_time,is_available) VALUES(?,?,?,?,1)'); $q->execute([$doctorId,$day,$start.':00',$end.':00']); }
            $pdo->commit(); generate_slots($pdo,$doctorId); flash('Schedule saved. Future slots have been generated.');
        } catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Could not save schedule.','error');} redirect('index.php?page=schedule');
    }
    if ($action==='create_doctor') {
        require_role('admin'); $name=trim($_POST['full_name']??''); $email=strtolower(trim($_POST['email']??'')); $password=$_POST['password']??''; $specialty=trim($_POST['specialty']??''); $qualification=trim($_POST['qualification']??''); $experience=max(0,(int)($_POST['experience_years']??0)); $fee=max(0,(float)($_POST['consultation_fee']??0));
        if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||$specialty===''){flash('Name, valid email, specialty, and password (8+ characters) are required.','error');redirect('index.php?page=admin_doctors');}
        try{$pdo->beginTransaction();$q=$pdo->prepare("INSERT INTO users(full_name,email,password_hash,role) VALUES(?,?,?,'doctor')");$q->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$uid=(int)$pdo->lastInsertId();$q=$pdo->prepare('INSERT INTO doctors(user_id,specialty,qualification,experience_years,consultation_fee) VALUES(?,?,?,?,?)');$q->execute([$uid,$specialty,$qualification,$experience,$fee]);$pdo->commit();flash('Doctor account created. Share the login credentials securely.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('Could not create doctor. Email may already exist.','error');} redirect('index.php?page=admin_doctors');
    }
    if ($action==='toggle_doctor') {
        require_role('admin'); $uid=(int)($_POST['user_id']??0); $pdo->prepare('UPDATE users SET is_active=IF(is_active=1,0,1) WHERE user_id=? AND role=\'doctor\'')->execute([$uid]); flash('Doctor account status updated.'); redirect('index.php?page=admin_doctors');
    }
}

function header_html(string $title): void {
    $u=current_user(); $f=$_SESSION['_flash']??null; unset($_SESSION['_flash']);
    echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'.e($title).' | '.e(APP_NAME).'</title><link rel="stylesheet" href="frontend/assets/style.css"></head><body><header class="topbar"><a class="brand" href="index.php">✚ '.e(APP_NAME).'</a><nav><a href="index.php?page=doctors">Find Doctors</a>';
    if($u){echo '<a href="index.php?page=dashboard">Dashboard</a><a href="index.php?page=bookings">Appointments</a>'; if($u['role']==='doctor')echo '<a href="index.php?page=schedule">My Schedule</a>'; if($u['role']==='admin')echo '<a href="index.php?page=admin_doctors">Manage Doctors</a>'; echo '<a href="index.php?page=logout">Logout</a>';} else echo '<a href="index.php?page=login">Login</a><a class="nav-cta" href="index.php?page=signup">Sign up</a>';
    echo '</nav></header><main class="container">'; if($f)echo '<div class="alert '.e($f['type']).'">'.e($f['message']).'</div>';
}
function footer_html(): void { echo '</main><footer>Doctor Appointment System · Academic project · Asia/Karachi</footer></body></html>'; }

if ($page==='home') { header_html('Home'); echo '<section class="hero"><div><span class="eyebrow">CARE, MADE SIMPLE</span><h1>Book the right doctor.<br><span>At the right time.</span></h1><p>Find doctors, explore available appointment slots, and manage your visits in one place.</p><a class="button" href="index.php?page=doctors">Browse doctors</a> <a class="button secondary" href="index.php?page=signup">Create patient account</a></div><div class="hero-card"><div class="medical-icon">✚</div><h3>Your health matters</h3><p>Easy scheduling with a clear view of available times.</p><div class="mini-row"><span>✓</span> Simple appointment booking</div><div class="mini-row"><span>✓</span> Manage upcoming visits</div><div class="mini-row"><span>✓</span> Doctor-managed schedules</div></div></section><section class="section"><h2>How it works</h2><div class="cards three"><article class="card"><span class="number">01</span><h3>Find a doctor</h3><p>Browse active doctors and specialties.</p></article><article class="card"><span class="number">02</span><h3>Choose a slot</h3><p>Select an available 30-minute appointment.</p></article><article class="card"><span class="number">03</span><h3>Manage visits</h3><p>View appointments and cancel eligible bookings.</p></article></div></section>'; footer_html(); exit; }
if ($page==='login') { header_html('Login'); echo '<div class="auth card"><h1>Welcome back</h1><p>Sign in to your account.</p><form method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="login"><label>Email</label><input type="email" name="email" required autocomplete="email"><label>Password</label><input type="password" name="password" required autocomplete="current-password"><button class="button full">Login</button></form><p class="muted">New patient? <a href="index.php?page=signup">Create an account</a></p></div>'; footer_html(); exit; }
if ($page==='signup') { header_html('Patient Sign Up'); echo '<div class="auth card"><h1>Create patient account</h1><p>Sign up to book appointments.</p><form method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="signup"><label>Full name</label><input name="full_name" required maxlength="120"><label>Email</label><input type="email" name="email" required><label>Password (minimum 8 characters)</label><input type="password" name="password" minlength="8" required><button class="button full">Create account</button></form><p class="muted">Already registered? <a href="index.php?page=login">Login</a></p></div>'; footer_html(); exit; }
if ($page==='doctors') { $search=trim($_GET['q']??''); $sql="SELECT d.doctor_id,d.specialty,d.qualification,d.experience_years,d.consultation_fee,d.bio,u.full_name FROM doctors d JOIN users u ON u.user_id=d.user_id WHERE u.is_active=1"; $args=[]; if($search!==''){$sql.=' AND (u.full_name LIKE ? OR d.specialty LIKE ?)';$args=['%'.$search.'%','%'.$search.'%'];} $sql.=' ORDER BY u.full_name';$q=$pdo->prepare($sql);$q->execute($args);$doctors=$q->fetchAll(); header_html('Find Doctors'); echo '<div class="page-heading"><div><span class="eyebrow">OUR DOCTORS</span><h1>Find your doctor</h1><p>Browse specialties and book an available appointment.</p></div><form class="search" method="get"><input type="hidden" name="page" value="doctors"><input name="q" placeholder="Name or specialty" value="'.e($search).'"><button class="button">Search</button></form></div><div class="cards three">'; foreach($doctors as $d){ echo '<article class="card doctor-card"><div class="avatar">✚</div><h3>Dr. '.e($d['full_name']).'</h3><span class="tag">'.e($d['specialty']).'</span><p>'.e($d['qualification']?:'Qualified medical professional').'</p><p class="muted">'.(int)$d['experience_years'].' years experience</p><p class="price">PKR '.number_format((float)$d['consultation_fee'],2).'</p><a class="button full" href="index.php?page=doctor&id='.(int)$d['doctor_id'].'">View availability</a></article>'; } if(!$doctors)echo '<p>No active doctors found yet. An administrator must add doctors first.</p>'; echo '</div>'; footer_html(); exit; }
if ($page==='doctor') { $id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT d.*,u.full_name FROM doctors d JOIN users u ON u.user_id=d.user_id WHERE d.doctor_id=? AND u.is_active=1');$q->execute([$id]);$d=$q->fetch(); if(!$d){flash('Doctor not found.','error');redirect('index.php?page=doctors');} generate_slots($pdo,$id);$q=$pdo->prepare("SELECT * FROM appointment_slots WHERE doctor_id=? AND status='available' AND start_at>NOW() ORDER BY start_at");$q->execute([$id]);$slots=$q->fetchAll();header_html('Doctor Availability');echo '<a class="back" href="index.php?page=doctors">← All doctors</a><section class="profile card"><div class="avatar large">✚</div><div><span class="tag">'.e($d['specialty']).'</span><h1>Dr. '.e($d['full_name']).'</h1><p>'.e($d['qualification']?:'Medical professional').' · '.(int)$d['experience_years'].' years experience</p><p>'.nl2br(e($d['bio']??'' )).'</p><p class="price">Consultation fee: PKR '.number_format((float)$d['consultation_fee'],2).'</p></div></section><h2>Available appointments</h2><p class="muted">Appointments are 30 minutes. Times are shown in Pakistan time.</p><div class="slot-grid">';foreach($slots as $s){echo '<article class="slot"><strong>'.e(date('D, d M',strtotime($s['start_at']))).'</strong><span>'.e(date('h:i A',strtotime($s['start_at']))).' – '.e(date('h:i A',strtotime($s['end_at']))).'</span>';if(current_user()&&current_user()['role']==='patient')echo '<form method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="book"><input type="hidden" name="slot_id" value="'.(int)$s['slot_id'].'"><button class="button full">Book slot</button></form>';else echo '<a class="button full" href="index.php?page=login">Login to book</a>';echo '</article>';}if(!$slots)echo '<p>No upcoming slots are available. Please check again later.</p>';echo '</div>';footer_html();exit; }
if ($page==='dashboard') { require_login();$u=current_user();header_html('Dashboard');echo '<div class="page-heading"><div><span class="eyebrow">YOUR WORKSPACE</span><h1>Hello, '.e($u['full_name']).'</h1><p>Signed in as '.e(ucfirst($u['role'])).'.</p></div></div><div class="cards three">';if($u['role']==='patient'){echo '<article class="card"><h3>Find a doctor</h3><p>Browse doctors and available slots.</p><a class="text-link" href="index.php?page=doctors">Browse doctors →</a></article><article class="card"><h3>My appointments</h3><p>Review upcoming and past appointments.</p><a class="text-link" href="index.php?page=bookings">View appointments →</a></article>';}elseif($u['role']==='doctor'){echo '<article class="card"><h3>My schedule</h3><p>Set your weekly working hours.</p><a class="text-link" href="index.php?page=schedule">Edit schedule →</a></article><article class="card"><h3>My appointments</h3><p>Review and manage your patient appointments.</p><a class="text-link" href="index.php?page=bookings">View appointments →</a></article>';}else{echo '<article class="card"><h3>Manage doctors</h3><p>Create or deactivate doctor accounts.</p><a class="text-link" href="index.php?page=admin_doctors">Manage doctors →</a></article><article class="card"><h3>All appointments</h3><p>Review appointments across the system.</p><a class="text-link" href="index.php?page=bookings">View appointments →</a></article>';}echo '</div>';footer_html();exit; }
if ($page==='schedule') {require_role('doctor');$did=doctor_id_for_user($pdo,(int)current_user()['user_id']);$q=$pdo->prepare('SELECT * FROM doctor_schedules WHERE doctor_id=?');$q->execute([$did]);$sched=[];foreach($q->fetchAll() as $s)$sched[(int)$s['day_of_week']]=$s;$days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',7=>'Sunday'];header_html('My Schedule');echo '<h1>Weekly schedule</h1><p>Set one continuous working period per day. Available slots are generated in 30-minute increments for the next 7 days.</p><form method="post" class="card schedule-form"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="save_schedule"><div class="schedule-head"><span>Day</span><span>Available</span><span>Start</span><span>End</span></div>';foreach($days as $n=>$day){$s=$sched[$n]??null;echo '<div class="schedule-row"><strong>'.e($day).'</strong><label class="check"><input type="checkbox" name="enabled['.$n.']" value="1" '.($s?'checked':'').'> Enable</label><input type="time" name="start['.$n.']" value="'.e($s?substr($s['start_time'],0,5):'09:00').'" aria-label="'.e($day).' start"><input type="time" name="end['.$n.']" value="'.e($s?substr($s['end_time'],0,5):'17:00').'" aria-label="'.e($day).' end"></div>';}echo '<button class="button">Save schedule</button></form>';footer_html();exit;}
if ($page==='admin_doctors') {require_role('admin');$q=$pdo->query("SELECT d.doctor_id,d.specialty,u.user_id,u.full_name,u.email,u.is_active FROM doctors d JOIN users u ON u.user_id=d.user_id ORDER BY u.full_name");$docs=$q->fetchAll();header_html('Manage Doctors');echo '<h1>Manage doctors</h1><p>Create doctor accounts here. Public signup can only create patient accounts.</p><form method="post" class="card form-grid"><h2 class="span-all">Add a doctor</h2><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="create_doctor"><label>Full name<input name="full_name" required></label><label>Email<input type="email" name="email" required></label><label>Temporary password (8+ chars)<input type="password" name="password" minlength="8" required></label><label>Specialty<input name="specialty" required></label><label>Qualification<input name="qualification"></label><label>Experience (years)<input type="number" name="experience_years" min="0" value="0"></label><label>Fee (PKR)<input type="number" name="consultation_fee" min="0" step="0.01" value="0"></label><button class="button span-all">Create doctor account</button></form><h2>Existing doctors</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Specialty</th><th>Status</th><th>Action</th></tr></thead><tbody>';foreach($docs as $d){echo '<tr><td>'.e($d['full_name']).'</td><td>'.e($d['email']).'</td><td>'.e($d['specialty']).'</td><td><span class="status '.((int)$d['is_active']?'confirmed':'cancelled').'">'.((int)$d['is_active']?'Active':'Inactive').'</span></td><td><form method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="toggle_doctor"><input type="hidden" name="user_id" value="'.(int)$d['user_id'].'"><button class="button small '.((int)$d['is_active']?'danger':'').'">'.((int)$d['is_active']?'Deactivate':'Activate').'</button></form></td></tr>';}if(!$docs)echo '<tr><td colspan="5">No doctors have been added.</td></tr>';echo '</tbody></table></div>';footer_html();exit;}
if ($page==='bookings') {require_login();$u=current_user();$params=[];$where='';if($u['role']==='patient'){$where='WHERE a.patient_id=?';$params[]=$u['user_id'];}elseif($u['role']==='doctor'){$where='WHERE d.user_id=?';$params[]=$u['user_id'];}$sql="SELECT a.appointment_id,a.status,a.booked_at,s.start_at,s.end_at,pu.full_name AS patient_name,du.full_name AS doctor_name,d.specialty,d.user_id AS doctor_user_id,a.patient_id FROM appointments a JOIN appointment_slots s ON s.slot_id=a.slot_id JOIN doctors d ON d.doctor_id=s.doctor_id JOIN users du ON du.user_id=d.user_id JOIN users pu ON pu.user_id=a.patient_id $where ORDER BY s.start_at DESC";$q=$pdo->prepare($sql);$q->execute($params);$rows=$q->fetchAll();header_html('Appointments');echo '<h1>'.($u['role']==='patient'?'My appointments':($u['role']==='doctor'?'Patient appointments':'All appointments')).'</h1><div class="table-wrap"><table><thead><tr><th>Date & time</th>';if($u['role']!=='patient')echo '<th>Patient</th>';if($u['role']!=='doctor')echo '<th>Doctor</th>';echo '<th>Status</th><th>Actions</th></tr></thead><tbody>';foreach($rows as $a){echo '<tr><td>'.e(date('D, d M Y',strtotime($a['start_at']))).'<br>'.e(date('h:i A',strtotime($a['start_at']))).' – '.e(date('h:i A',strtotime($a['end_at']))).'</td>';if($u['role']!=='patient')echo '<td>'.e($a['patient_name']).'</td>';if($u['role']!=='doctor')echo '<td>Dr. '.e($a['doctor_name']).'<br><small>'.e($a['specialty']).'</small></td>';echo '<td><span class="status '.e($a['status']).'">'.e(ucfirst($a['status'])).'</span></td><td class="actions">';$future=strtotime($a['start_at'])>time();$owns=$u['role']==='admin'||($u['role']==='patient'&&(int)$a['patient_id']===(int)$u['user_id'])||($u['role']==='doctor'&&(int)$a['doctor_user_id']===(int)$u['user_id']);if($a['status']==='confirmed'&&$future&&$owns){echo '<form method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="cancel"><input type="hidden" name="appointment_id" value="'.(int)$a['appointment_id'].'"><button class="button small danger">Cancel</button></form>';}if(in_array($u['role'],['doctor','admin'],true)&&$a['status']==='confirmed'&&!$future&&$owns){echo '<form method="post"><input type="hidden" name="_csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="complete"><input type="hidden" name="appointment_id" value="'.(int)$a['appointment_id'].'"><button class="button small">Mark completed</button></form>';}if(!$owns||($a['status']!=='confirmed'||(!$future&&$u['role']==='patient')))echo '—';echo '</td></tr>';}if(!$rows)echo '<tr><td colspan="5">No appointments found.</td></tr>';echo '</tbody></table></div>';footer_html();exit;}
header_html('Page');echo '<h1>Page not found</h1>';footer_html();
